<template>
  <div class="container" v-loading="loading">
    <div class="vote_add_top" @click="return_vote_list_add">
      <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回
    </div>
    <div class="container-box">
      <div class="editbox">
        <!-- 标题 -->
        <div class="title">
          <div class="title_box">
          {{template_title}}
          </div>
        </div>


        <div class="list" id="list" :style="{backgroundImage: template_img, width: template_width, backgroundSize : '100% auto', backgroundRepeat: 'no-repeat'}">
          <img :src="template_img_box" ref="template_img_box_display" :style="{width: template_width, 'height': 'auto'}">
          <div v-for="(rect, index) in rects">
            <div :style="{position: 'absolute','-webkit-box-sizing': 'border-box','box-sizing': 'border-box',top: rect.top+'px', left: rect.left+'px', width: rect.width+'px', height: rect.height+'px'}">
              <input class="filler" v-if="rect['type'] && rect['type']=='txt'" type="text" :style="{backgroundColor:rect.backgroundColor,color:rect.color, width:rect.width+'px', height:rect.height+'px', boxShadow:'0 2px 10px #999'}" v-model="rect['value']" :placeholder="rect['type_text']"/>
              <textarea
                class="filler"
                v-if="rect['type'] && rect['type']=='mul_txt'"
                :style="{'z-index': rect.zIndex+1,overflow:'hidden',resize:'none','padding':'5px','text-align': 'left',backgroundColor:rect.backgroundColor,color:rect.color, width:(rect.width-10)+'px', height:(rect.height-10)+'px', boxShadow:'0 2px 10px #999'}"
                :placeholder="rect['type_text']"
                v-model="rect['value']">
              </textarea>
              <el-date-picker
                style="opacity:0;"
                :style="{'z-index': rect.zIndex+1,lineHeight:rect.height+'px', backgroundColor:rect.backgroundColor,color:rect.color, width:rect.width+'px', height:rect.height+'px', boxShadow:'0 2px 10px #999'}"
                class="filler"
                :editable="false"
                value-format="yyyy-MM-dd"
                format="yyyy-MM-dd"
                v-model="rect['value']" v-if="rect['type'] && rect['type']=='date_choose'"
                type="date"
                size="mini"
                :placeholder="rect['type_text']">
              </el-date-picker>
              <div class="filler" v-if="rect['type'] && rect['type']=='date_choose'" style="text-align: -webkit-center;" :style="{backgroundColor:rect.backgroundColor,color:rect.color, width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                <span v-if="rect['value']">{{rect['value']}}</span>
                <span v-if="!rect['value']">{{rect['type_text']}}</span>
              </div>
              <div class="filler" @click="template_add(rect, index)" v-if="rect['type'] && rect['type']!='txt' && rect['type']!='date_choose' && rect['type']!='mul_txt'" style="text-align: -webkit-center;" :style="{backgroundColor:rect.backgroundColor,color:rect.color, width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px', boxShadow:'0 2px 10px #999'}">
                <span v-if="rect['value']">{{rect['value']}}</span>
                <span v-if="!rect['value']">{{rect['type_text']}}</span>
              </div>
              <div class="close_block" @click="close_block(index)" :style="{'z-index':rect.zIndex+2}">×</div>
            </div>
          </div>
        </div>

        <div class="list"  style="display: none;" ref="list_box" :style="{backgroundImage: template_img, width: template_width, backgroundSize : '100% auto', backgroundRepeat: 'no-repeat'}">
          <img :src="template_img_box" ref="template_img_box_display" :style="{width: template_width, 'height': 'auto'}">
          <div v-for="(rect, index) in rects">
            <div :style="{position: 'absolute','-webkit-box-sizing': 'border-box','box-sizing': 'border-box',top: rect.top+'px', left: rect.left+'px', width: rect.width+'px', height: rect.height+'px'}">
              <div class="filler" v-if="rect['type'] && rect['type']=='mul_txt'" style="text-align: -webkit-left;" :style="{'z-index': rect.zIndex+1,overflow:'hidden','padding':'5px','text-align': 'left', width:(rect.width-10)+'px', height:(rect.height-10)+'px'}">
                <span v-if="rect['value']">{{rect['value']}}</span>
                <span v-if="!rect['value']">{{rect['type_text']}}</span>
              </div>
              <div class="filler" v-if="rect['type'] && rect['type']!='mul_txt'" style="text-align: -webkit-center;" :style="{width:rect.width+'px', height:rect.height+'px',lineHeight:rect.height+'px'}">
                <span v-if="rect['value']">{{rect['value']}}</span>
                <span v-if="!rect['value']">{{rect['type_text']}}</span>
              </div>
            </div>
          </div>
        </div>


      </div>

      <el-row class="finish_box">
        <el-col :span="12">
          <el-button class="save_btn" type="primary" @click="finish_vote">保存</el-button>
        </el-col>
        <el-col :span="12">
          <el-button class="save_btn" type="primary" @click="save_print">保存并打印</el-button>
        </el-col>
      </el-row>



      <!-- 弹出层 -->
      <el-dialog :title="choose_title" :visible.sync="dialogFormVisible" width="450px">
        <el-row>
          <el-col :span="12">
            <el-input class="choose_dialog_input"
                      type="text"
                      placeholder="请输入内容"
                      v-model="choose_val"
                      size="mini">
            </el-input>
          </el-col>
          <el-col :span="2">
            &nbsp;
          </el-col>
          <el-col :span="10">
            <el-button class="true_input" size="mini"  type="primary" @click="clickUse(0)">确认使用填写内容</el-button>
          </el-col>
        </el-row>


        <el-row style="padding: 10px 0;">
          <el-col :span="12">
            <el-input class="choose_dialog_input"
                      type="text"
                      placeholder="请输入搜索内容"
                      v-model="search_val"
                      size="mini">
            </el-input>
          </el-col>
          <el-col :span="2">
            &nbsp;
          </el-col>
          <el-col :span="10">
            <el-button class="true_input" size="mini"  type="primary" @click="search">点击搜索</el-button>
          </el-col>
        </el-row>

        <el-table
          class="list_table"
          :data="choose_data"
          style="width:100%"
          :height="400">
          <el-table-column
            prop="choose_info"
            label="所选信息"
            min-width="300">
          </el-table-column>
          <el-table-column
            label="操作"
            width="150">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click.native.prevent="clickTrue(scope.$index, choose_data)">点击选中</el-button>
            </template>
          </el-table-column>
        </el-table>

        <div style="width: 100%;text-align: -webkit-center;padding: 20px 0;">
          <el-footer style="padding: 0;">
            <div v-show="total_page>0" class="page_msg">
              <el-pagination
                background
                layout="prev, pager, next"
                :page-count="total_page"
                :current-page="page"
                @current-change="current_change"
              >
              </el-pagination>
            </div>
          </el-footer>
        </div>
      </el-dialog>

    </div>
  </div>
</template>

<script>
  export default {
    name: 'add_template',
    data() {
      return {
        choose_type: 'txt',
        choose_val: '',
        choose_index: '',
        page: 1,
        total_page: 1,
        pagerCount: 3,
        choose_data: [],
        dialogFormVisible: false,
        choose_title: '选择',
        floor_list: [],
        owner_list: [],
        template_img: '',
        template_img_box: '',
        template_width: '800px',
        zIndexMax: 3,
        rects: [],
        template_img_val: '', // 上传的背景图片
        template_title: '', // 模板标题
        add_material_btn: [
          '单行文本',
          '多行文本',
          '单元选择框',
          '业主姓名选择框',
          '业主联系方式框',
          '时间选择框',
        ],
        loading: false,
        diy_id: '',
        template_id: '',
        template_title_placeholder: '请输入模板标题',
        is_click: false,
        key_num: 0,
        custom_write: {},
        paths: '',
        search_val: '',
        hkey_root: 'HKEY_CURRENT_USER',
        hkey_path: '\\Software\\Microsoft\\Internet Explorer\\PageSetup\\',
        hkey_key: '',
      }
    },
    created () {
      this.template_id = this.$route.query.template_id;
      this.diy_id = this.$route.query.diy_id;
      this.paths = this.$route.query.paths;
      if (this.template_id>0) {
        let param = {};
        param['template_id'] = this.template_id;
        this.templateDetail(param);
      } else if(this.diy_id>0) {
        let param = {};
        param['diy_id'] = this.diy_id;
        this.templateWriteDetail(param);
      } else {
        this.$message({
          type: 'info',
          message: '缺少必要参数'
        });
        this.$router.replace({ path: '/template_list'});
      }
    },
    methods: {
      input_val(e) {
        console.log('input_val', e);
      },
      clickUse() {
        let index = this.choose_index;
        this.rects[index]['value'] = this.choose_val;
        this.dialogFormVisible = false;
      },
      clickTrue(index,rows) {
        let choose = rows[index];
        let indexs = this.choose_index;
        this.rects[indexs]['value'] = choose['msg'];
        if ('owner_choose'==this.choose_type) {
            for (let i in this.rects) {
              if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='owner_phone' && choose['phone']) {
                this.rects[i]['value'] = choose['phone'];
              } else if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='floor_choose' && choose['floor_name']) {
                this.rects[i]['value'] = choose['floor_name'];
              }
            }
        } else if ('owner_phone'==this.choose_type) {
          for (let i in this.rects) {
            if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='owner_choose' && choose['name']) {
              this.rects[i]['value'] = choose['name'];
            } else if (this.rects[i] && !this.rects[i]['value'] && this.rects[i]['type']=='floor_choose' && choose['floor_name']) {
              this.rects[i]['value'] = choose['floor_name'];
            }
          }
        }
        this.dialogFormVisible = false;
      },
      template_add(info, index) {
        this.dialogFormVisible = true;
        this.choose_type = info['type'];
        this.choose_index = index;
        this.choose_val = info['value'];
        this.page = 1;
        this.choose_data = [];
        this.search_val = '';
        this.chooseMsg()
      },
      search() {
        let search_val = this.search_val
        if (!search_val) {
          this.$message({
            type: 'info',
            message: '请填写搜索内容!'
          });
        } else {
          this.chooseMsg()
        }
      },
      // 获取需要选的信息
      async chooseMsg() {
        let param = {};
        param['type'] = this.choose_type;
        param['page'] = this.page;
        param['search_val'] = this.search_val;
        let res = await this.$api.chooseMsg(param);
        if (res) {
          this.choose_data = res.list;
          this.total_page = res.total_page;
        }
        console.log('chooseMsg', this.choose_data);
      },
      current_change(val) {
        this.page = val;
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
        let param = {};
        param['type'] = this.choose_type;
        this.chooseMsg(param)
      },
      selectChange(index) {
        console.log('selectChangeVal', this.rects[index]);
        if (-1 == this.rects[index]['value']) {
          if (!this.custom_write) {
            this.custom_write = {};
          }
          this.custom_write[index] = true;
        }
        console.log('custom_write', this.custom_write);
      },
      custom_write_click(index) {
        console.log('custom_write_click', index);
        this.custom_write[index] = true;
      },
      custom_write_no(index) {
        console.log('custom_write_no', index);
        if (!this.custom_write) {
          this.custom_write = {};
        }
        this.custom_write[index] = false;
        console.log('custom_write1', this.custom_write);
      },
      date_choose(index) {
        console.log('date_choose', index);
        // this.$refs.choose_data[index].click();
      },
      return_vote_list_add: function () {
        if (this.paths && 'write_list'==this.paths && this.template_id) {
          this.$router.replace({ path: '/write_list', query: { template_id: this.template_id}});
        } else {
          this.$router.replace({ path: '/template_list'});
        }
      },
      close_block(index) {
        console.log('close_block',index);
        this['rects'][index]['is_close'] = true;
        this.rects.splice(index,1);
      },
      // 获取投票详情
      async templateDetail(param) {
        let res = await this.$api.templateDetail(param);
        if (res) {
          console.log(`templateDetail: `, res);
          this.rects = res.template_content;
          console.log(`rects: `, this.rects);
          this.template_title = res.template_title;
          this.template_img_val = res.template_img;
          this.template_img = 'url('+res.template_img_path+')';
          this.template_img_box = res.template_img_path;
          if (res.template_width) {
            this.template_width = res.template_width;
          }
        }
      },
      // 获取投票详情
      async templateWriteDetail(param) {
        let res = await this.$api.templateWriteDetail(param);
        if (res) {
          console.log(`templateDetail: `, res);
          this.rects = res.diy_value;
          console.log(`rects: `, this.rects);
          this.template_title = res.title;
          this.template_img_val = res.template_img;
          this.template_img = 'url('+res.template_img_path+')';
          this.template_img_box = res.template_img_path;
          this.template_id = res.template_id;
          if (res.template_width) {
            this.template_width = res.template_width;
          }
        }
      },
      // 编辑投票
      async editDiyValue(param) {
        let res = await this.$api.editDiyValue(param);
        let _this=this;
        if (res) {
          _this.$message({
            type: 'success',
            message: '修改成功!'
          });
          _this.$router.replace({ path: '/write_list', query: { template_id: this.template_id}});
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      // 添加填写信息
      async addDiyValue(param) {
        let res = await this.$api.addDiyValue(param);
        let _this=this;
        if (res) {
          _this.$message({
            type: 'success',
            message: '添加成功!'
          });
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        _this.$router.replace({ path: '/write_list', query: { template_id: this.template_id}});
        return res;
      },
      finish_vote: function(e) {
        console.log('rects结果：',this.rects);
        console.log('template_img_val结果：',this.template_img_val);
        console.log('template_title结果：',this.template_title);
        if (!this.template_title) {
          console.log('err：',1);
          this.$message({
            message: '请输入模板标题',
            type: 'warning'
          });
          return false;
        }
        if (!this.template_img_val) {
          this.$message({
            message: '请上传背景图片',
            type: 'warning'
          });
          return false;
        }
        if (!this.rects) {
          this.$message({
            message: '最少选择一个选框',
            type: 'warning'
          });
          return false;
        }
        let param = {};
        param['diy_value'] = this.rects;
        param['template_img'] = this.template_img_val;
        param['template_title'] = this.template_title;
        param['template_width'] = this.template_width;
        param['template_id'] = this.template_id;
        console.log('param：',param);
        if (this.diy_id && this.diy_id>0) {
          param['diy_id'] = this.diy_id;
          this.editDiyValue(param);
        } else {
          this.addDiyValue(param);
        }
      },
      up_img: function() {
        console.log('触发上传图片')
        this.$refs.tempUploadFile.click();
      },
      focus_title(e) {
        console.log('focus_title')
        if(e.target && this.vote_title_placeholder){
          this.vote_title_placeholder = '';
        }
      },
      blur_title(e) {
        if(e.target && !this.vote_title_placeholder){
          this.vote_title_placeholder = '请输入表单标题';
        }
      },
      //
      PageSetup_Null() {
        try{
          let RegWsh = new ActiveXObject("WScript.Shell") ;
          this.hkey_key = "header";
          RegWsh.RegWrite (this.hkey_root + this.hkey_path + this.hkey_key,"") ;
          this.hkey_key = "footer" ;
          RegWsh.RegWrite(this.hkey_root + this.hkey_path + this.hkey_key,"") ;
        }
        catch(e){}
      },
      save_print() {
        if (!this.template_title) {
          console.log('err：',1);
          this.$message({
            message: '请输入模板标题',
            type: 'warning'
          });
          return false;
        }
        if (!this.template_img_val) {
          this.$message({
            message: '请上传背景图片',
            type: 'warning'
          });
          return false;
        }
        if (!this.rects) {
          this.$message({
            message: '最少选择一个选框',
            type: 'warning'
          });
          return false;
        }
        let param = {};
        param['diy_value'] = this.rects;
        param['template_img'] = this.template_img_val;
        param['template_title'] = this.template_title;
        param['template_width'] = this.template_width;
        param['template_id'] = this.template_id;
        let res='';
        if (this.diy_id && this.diy_id>0) {
          param['diy_id'] = this.diy_id;
          res = this.editDiyValue(param);
        } else {
          res = this.addDiyValue(param);
        }
        console.log('save_print_res：',res);
        if (res) {
          console.log('save_print', 1);
          this.PageSetup_Null() ;
          if (window.PrePrint != null) window.PrePrint();
          try{
            print.portrait   =  false    ;//横向打印
          }catch(e){
            // alert("不支持此方法");
          }
          var bdhtml = window.document.body.innerHTML;//获取当前页的html代码
          // var sprnstr="<!--begin-->";//设置打印开始区域
          // var eprnstr="<!--end-->";//设置打印结束区域
          // var prnhtml=bdhtml.substring(bdhtml.indexOf(sprnstr)); //从开始代码向后取html
          // var prnhtml=prnhtml.substring(0,prnhtml.indexOf(eprnstr));//从结束代码向前取html
          var prnhtml = this.$refs.list_box.innerHTML;//从结束代码向前取html
          window.document.body.innerHTML=prnhtml;
          window.print();
          setTimeout("window.location.reload();", 80);
          window.document.body.innerHTML=bdhtml;
          // PageSetup_Default() ;
        }
      }
    }
  }
</script>
<style>
  .container input{
    cursor:pointer;
  }
</style>
<style media="print">
  @page {
    size: auto;  /* auto is the initial value */
    margin: 2mm; /* this affects the margin in the printer settings */
  }
</style>
